(1473609, 193492, 21478, '<td valign="top">very nice - great perspective</td>', 'very nice - great perspective', '2005-06-22 06:54:37.000000', NULL, 1),
(1473611, 192942, 21478, '<td valign="top">good concept but a little dull in the execution. Perhaps a bit more light reflecting off the metal?</td>', 'good concept but a little dull in the execution. Perhaps a bit more light reflecting off the metal?', '2005-06-22 06:55:04.000000', NULL, 1),
(1473612, 192354, 21478, '<td valign="top">great close-up, perhaps a bit of motion would have been nice - although I understand hard to capture.</td>', 'great close-up, perhaps a bit of motion would have been nice - although I understand hard to capture.', '2005-06-22 06:55:40.000000', NULL, 1),
