INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1474055, 191990, 39430, '<td valign="top">Great angle, and great mix of subject and background.  This is really well done.</td>', 'Great angle, and great mix of subject and background.  This is really well done.', '2005-06-22 09:44:36.000000', NULL, 1),
(1474057, 192225, 36499, '<td valign="top">excellent..how did u keep from getting blown highlights? and no reflection of u in all that chrome either! great color,contrast,crop.and no noise (without photo looking fake!)..all great 10</td>', 'excellent..how did u keep from getting blown highlights? and no reflection of u in all that chrome either! great color,contrast,crop.and no noise (without photo looking fake!)..all great 10', '2005-06-22 09:45:36.000000', NULL, 1),
