INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1474448, 192936, 24073, '<td valign="top">Captivating, it takes me back, and photos like that are priceless.  The X factor, you got it.  Time in a bottle.  Ty for entering, and GL.</td>', 'Captivating, it takes me back, and photos like that are priceless.  The X factor, you got it.  Time in a bottle.  Ty for entering, and GL.', '2005-06-22 11:18:58.000000', NULL, 1),
(1474450, 193102, 35804, '<td valign="top">The reflections are a tad distracting...when I photograph these wonderful chrome laden beasts...I try to make sure I''m never in the picture...try different angles so atleast the reflections are really "stretched"...seems to work for me.</td>', 'The reflections are a tad distracting...when I photograph these wonderful chrome laden beasts...I try to make sure I''m never in the picture...try different angles so atleast the reflections are really "stretched"...seems to work for me.', '2005-06-22 11:19:27.000000', NULL, 1),
(1474451, 191430, 39336, '<td valign="top">Maybe if the background was a plain color it would look better.</td>', 'Maybe if the background was a plain color it would look better.', '2005-06-22 11:19:30.000000', NULL, 1),
(1474452, 192841, 39226, '<td valign="top">I love the lightning effect, but the city lights beyond the fingertips spoil the effect.  I really appreciate what you were trying to achieve with this image.  Keep up the good work!</td>', 'I love the lightning effect, but the city lights beyond the fingertips spoil the effect.  I really appreciate what you were trying to achieve with this image.  Keep up the good work!', '2005-06-22 11:19:38.000000', NULL, 1),
