(1476201, 190513, 33732, '<td valign="top">Dark</td>', 'Dark', '2005-06-22 18:42:44.000000', NULL, 1),
(1476202, 194074, 29601, '<td valign="top">nice angle, but it seems somewhat out of focus.</td>', 'nice angle, but it seems somewhat out of focus.', '2005-06-22 18:42:48.000000', NULL, 1),
