(1476222, 193954, 37875, '<td valign="top">Great subject, great angle, great lighting, great shot!</td>', 'Great subject, great angle, great lighting, great shot!', '2005-06-22 18:46:34.000000', NULL, 1),
(1476225, 191558, 37719, '<td valign="top">With all the possibilities for this challenge and they were endless I can''t get past the fact this is someone elses artwork.</td>', 'With all the possibilities for this challenge and they were endless I can''t get past the fact this is someone elses artwork.', '2005-06-22 18:46:35.000000', NULL, 1),
