(1476637, 192256, 37875, '<td valign="top">The sky is cool, and I like how the sword is placed in the photo, but there''s something about the color of the blade that causes it to lose its detail.  That detracts from the photo for me.</td>', 'The sky is cool, and I like how the sword is placed in the photo, but there''s something about the color of the blade that causes it to lose its detail.  That detracts from the photo for me.', '2005-06-22 20:27:58.000000', NULL, 1),
(1476641, 191075, 37875, '<td valign="top">This may have been more effective if taken at a greater angle.  I like the concept.</td>', 'This may have been more effective if taken at a greater angle.  I like the concept.', '2005-06-22 20:29:07.000000', NULL, 1),
(1476647, 193951, 34591, '<td valign="top">Excellent color and lighting. Good job!</td>', 'Excellent color and lighting. Good job!', '2005-06-22 20:30:56.000000', NULL, 1),
(1476648, 192932, 34591, '<td valign="top">Love it. Great picture.</td>', 'Love it. Great picture.', '2005-06-22 20:31:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1476649, 194058, 37875, '<td valign="top">I don''t know why, but I love this photo.  I love the feel, the light, the softness, the idea.  Good luck!</td>', 'I don''t know why, but I love this photo.  I love the feel, the light, the softness, the idea.  Good luck!', '2005-06-22 20:32:18.000000', NULL, 1),
(1476657, 192931, 37875, '<td valign="top">Cool shot!  The lighting on and under the bus make the image a bit washed out for my taste...</td>', 'Cool shot!  The lighting on and under the bus make the image a bit washed out for my taste...', '2005-06-22 20:34:20.000000', NULL, 1),
(1476684, 192917, 37200, '<td valign="top">well exposed against a bright sky.</td>', 'well exposed against a bright sky.', '2005-06-22 20:49:54.000000', NULL, 1),
(1476686, 193178, 37200, '<td valign="top">unique shot!</td>', 'unique shot!', '2005-06-22 20:51:20.000000', NULL, 1),
(1476692, 193139, 37200, '<td valign="top">wow!  talk about clean lines and great lighting!</td>', 'wow!  talk about clean lines and great lighting!', '2005-06-22 20:54:22.000000', NULL, 1),
(1476696, 192841, 15242, '<td valign="top">I''m sorry, but this is so horribly bad.  The ketchup, the background photo, a tack, the wordy title...  Next time at least cover up the cityscape lights in the background photo.</td>', 'I''m sorry, but this is so horribly bad.  The ketchup, the background photo, a tack, the wordy title...  Next time at least cover up the cityscape lights in the background photo.', '2005-06-22 20:55:08.000000', NULL, 1),
(1476700, 190676, 15242, '<td valign="top">Great photo, I could see this hanging in a golf guy''s office.  I like the detail and the crop.</td>', 'Great photo, I could see this hanging in a golf guy''s office.  I like the detail and the crop.', '2005-06-22 20:56:37.000000', NULL, 1),
(1476702, 192745, 37200, '<td valign="top">I like the fact that the rings look like they have been worn for ages.  Not real sure about the lighting..just a little harsh.  Too bad it wasn''t advanced editing...could have cloned out that thing that looks like a bugger on the child''s finger. :-)</td>', 'I like the fact that the rings look like they have been worn for ages.  Not real sure about the lighting..just a little harsh.  Too bad it wasn''t advanced editing...could have cloned out that thing that looks like a bugger on the child''s finger. :-)', '2005-06-22 20:57:20.000000', NULL, 1),
(1476703, 192476, 15242, '<td valign="top">Cool subjects but a very distracting background.</td>', 'Cool subjects but a very distracting background.', '2005-06-22 20:57:42.000000', NULL, 1),
(1476710, 191215, 37200, '<td valign="top">interesting object, could use a bit more DOF in my opinion.  I do like the crop as well.</td>', 'interesting object, could use a bit more DOF in my opinion.  I do like the crop as well.', '2005-06-22 20:59:13.000000', NULL, 1),
(1476712, 192595, 15242, '<td valign="top">If only I couldn''t see the entire room in the reflections...  Photographing chrome is difficult.</td>', 'If only I couldn''t see the entire room in the reflections...  Photographing chrome is difficult.', '2005-06-22 20:59:43.000000', NULL, 1),
(1476715, 192587, 15242, '<td valign="top">You could argue that it meets the challenge in an out of the box way, although the description was pretty clear, but how is it a good photo?  Plus, it''s way to small.</td>', 'You could argue that it meets the challenge in an out of the box way, although the description was pretty clear, but how is it a good photo?  Plus, it''s way to small.', '2005-06-22 21:01:30.000000', NULL, 1),
(1476717, 194075, 15242, '<td valign="top">Very nice in a wierd way.  I like the post processing.</td>', 'Very nice in a wierd way.  I like the post processing.', '2005-06-22 21:02:21.000000', NULL, 1),
(1476722, 191493, 15242, '<td valign="top">Didn''t want to try too hard on this one, huh?  Technically I''d say the shot is great and for the "sprite and homework" challenge I''d give it a 10, but it''s just not at all interesting to me.</td>', 'Didn''t want to try too hard on this one, huh?  Technically I''d say the shot is great and for the "sprite and homework" challenge I''d give it a 10, but it''s just not at all interesting to me.', '2005-06-22 21:06:32.000000', NULL, 1),
(1476733, 191176, 1647, '<td valign="top">The couple of people really add a sense of scale to the image and provide a nice little focus point.</td>', 'The couple of people really add a sense of scale to the image and provide a nice little focus point.', '2005-06-22 21:11:57.000000', NULL, 1),
(1476737, 193065, 1647, '<td valign="top">Great colour and exposure - perhaps needs a fraction of counter-clockwise rotation to square it up.</td>', 'Great colour and exposure - perhaps needs a fraction of counter-clockwise rotation to square it up.', '2005-06-22 21:12:36.000000', NULL, 1),
(1476738, 193097, 36495, '<td valign="top">This just doesn''t scream "metal" to me, but still nice.</td>', 'This just doesn''t scream "metal" to me, but still nice.', '2005-06-22 21:12:55.000000', NULL, 1),
