(1476740, 193032, 36495, '<td valign="top">This just doesn''t scream "metal" to me, but still nice. The path looks a little overexposed too.</td>', 'This just doesn''t scream "metal" to me, but still nice. The path looks a little overexposed too.', '2005-06-22 21:13:18.000000', NULL, 1),
(1476742, 193085, 36495, '<td valign="top">Like it.</td>', 'Like it.', '2005-06-22 21:13:37.000000', NULL, 1),
(1476743, 192757, 36495, '<td valign="top">Says "dog" more than "metal to me.</td>', 'Says "dog" more than "metal to me.', '2005-06-22 21:13:52.000000', NULL, 1),
