(1476760, 190875, 1647, '<td valign="top">The every so slight rotation / angle is distracting - not enough to be deliberate, just enough to be seen.</td>', 'The every so slight rotation / angle is distracting - not enough to be deliberate, just enough to be seen.', '2005-06-22 21:19:17.000000', NULL, 1),
(1476762, 190816, 38640, '<td valign="top">I ceep coming back to look at this picture, over and over again. Fantastic picture. Best of luck. Gave it 10.</td>', 'I ceep coming back to look at this picture, over and over again. Fantastic picture. Best of luck. Gave it 10.', '2005-06-22 21:20:19.000000', NULL, 1),
