(1477592, 192932, 22914, '<td valign="top">Good lighting.  Lucky to get a good sky behind.</td>', 'Good lighting.  Lucky to get a good sky behind.', '2005-06-23 05:31:48.000000', NULL, 1),
(1477594, 193045, 31443, '<td valign="top">Looks like a footbridge, strange looking contraption, good angle..</td>', 'Looks like a footbridge, strange looking contraption, good angle..', '2005-06-23 05:37:42.000000', NULL, 1),
(1477596, 192564, 31443, '<td valign="top">Good idea to put the greenery in there to cut up the image a bit, attractive for an otherwise mundane but then again not so mundane fence, but why the central focus?</td>', 'Good idea to put the greenery in there to cut up the image a bit, attractive for an otherwise mundane but then again not so mundane fence, but why the central focus?', '2005-06-23 05:39:36.000000', NULL, 1),
