INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1487762, 192941, 28742, '<td valign="top">Looks "Obsolete" - hope you took 2 shots of it. ;-)<br/>Nice job for this challenge as well though.</td>', 'Looks "Obsolete" - hope you took 2 shots of it. ;-)Nice job for this challenge as well though.', '2005-06-28 02:44:33.000000', NULL, 1),
(1487764, 191582, 28742, '<td valign="top">Very unique angle - haven''t seen this one before. Good, sharp focus at the top as well. Great job!</td>', 'Very unique angle - haven''t seen this one before. Good, sharp focus at the top as well. Great job!', '2005-06-28 02:45:53.000000', NULL, 1),
(1487814, 190908, 7743, '<td valign="top">This wide a view was probably used in order for viewers to be able to identify the object however the pattern of the blades is very interesting and I feel a closer crop would add to that interest.</td>', 'This wide a view was probably used in order for viewers to be able to identify the object however the pattern of the blades is very interesting and I feel a closer crop would add to that interest.', '2005-06-28 03:48:48.000000', NULL, 1),
(1487842, 191321, 38492, '<td valign="top">Nice colours and composition, but the regular noise in the sky is very distracting.</td>', 'Nice colours and composition, but the regular noise in the sky is very distracting.', '2005-06-28 04:43:54.000000', NULL, 1),
(1487845, 192571, 38492, '<td valign="top">I really can''t see metal in this picture - the water beads are the main subject that the eye sees. Nice capture, though.</td>', 'I really can''t see metal in this picture - the water beads are the main subject that the eye sees. Nice capture, though.', '2005-06-28 04:46:01.000000', NULL, 1),
(1487856, 194082, 22748, '<td valign="top">Very creative!</td>', 'Very creative!', '2005-06-28 05:16:04.000000', NULL, 1),
(1487861, 192815, 22748, '<td valign="top">I like the texture of the metal, the lighting and the tones of the image. Cool.</td>', 'I like the texture of the metal, the lighting and the tones of the image. Cool.', '2005-06-28 05:29:56.000000', NULL, 1),
(1487867, 192342, 22748, '<td valign="top">I love how the background gradient and spoon gradient match each other. Great smooth image, really clean. Fabulous.</td>', 'I love how the background gradient and spoon gradient match each other. Great smooth image, really clean. Fabulous.', '2005-06-28 05:47:29.000000', NULL, 1),
(1487869, 192686, 22748, '<td valign="top">Kinda nice, but just way too dark, I can''t see detail.</td>', 'Kinda nice, but just way too dark, I can''t see detail.', '2005-06-28 05:49:39.000000', NULL, 1),
(1487870, 192587, 22748, '<td valign="top">Way too small. Try using a bigger size.</td>', 'Way too small. Try using a bigger size.', '2005-06-28 05:49:52.000000', NULL, 1),
(1487872, 192682, 22748, '<td valign="top">Unique! Seems very useless in case of a fire though....</td>', 'Unique! Seems very useless in case of a fire though....', '2005-06-28 05:50:49.000000', NULL, 1),
(1487876, 193920, 22748, '<td valign="top">I think this could be a artistic, creative image, but there are several problems. First, the cutting off of the meter is in an awkward place. Including all or none of it would have been better. Also, there are bits of random objects in the scene, but don''t feel like an important part of the composition. The texture of the wall is interesting, however, and you could get closer to it to see more detail in the wall.</td>', 'I think this could be a artistic, creative image, but there are several problems. First, the cutting off of the meter is in an awkward place. Including all or none of it would have been better. Also, there are bits of random objects in the scene, but don''t feel like an important part of the composition. The texture of the wall is interesting, however, and you could get closer to it to see more detail in the wall.', '2005-06-28 05:55:14.000000', NULL, 1),
(1487877, 193951, 22748, '<td valign="top">Awesome image. So sharp. Great lighting on the wrenches, and the composition is great. I love this image.</td>', 'Awesome image. So sharp. Great lighting on the wrenches, and the composition is great. I love this image.', '2005-06-28 05:56:11.000000', NULL, 1),
(1487905, 194073, 39649, '<td valign="top">This has potential but it looks slightly out of focus to me. In a photo like this, I would expect pin-sharp focus.</td>', 'This has potential but it looks slightly out of focus to me. In a photo like this, I would expect pin-sharp focus.', '2005-06-28 06:43:22.000000', NULL, 1),
(1487909, 190622, 39553, '<td valign="top">Nice sculpture... shame about the pile of rubble!</td>', 'Nice sculpture... shame about the pile of rubble!', '2005-06-28 06:45:53.000000', NULL, 1),
(1487913, 192674, 39649, '<td valign="top">Seems a bit soft. I wonder if that was intentional?</td>', 'Seems a bit soft. I wonder if that was intentional?', '2005-06-28 06:49:46.000000', NULL, 1),
