(1490964, 193919, 22734, '<td valign="top">Congratulations on your top ten finish. This image rocks!</td>', 'Congratulations on your top ten finish. This image rocks!', '2005-06-29 11:16:38.000000', NULL, 0),
(1490969, 191419, 22734, '<td valign="top">The best of the close ups. Congratulations on your top Ten finish.</td>', 'The best of the close ups. Congratulations on your top Ten finish.', '2005-06-29 11:17:33.000000', NULL, 0),
(1490974, 192907, 7743, '<td valign="top">I think they were confused as to what paint colour to use so they just used all the leftovers from the other airlines (to save money).<br/> <br/>It''s a very colourful photo however the plane is trapped in the frame.  More space on the left and the top would give it some space to fly into.</td>', 'I think they were confused as to what paint colour to use so they just used all the leftovers from the other airlines (to save money). It''s a very colourful photo however the plane is trapped in the frame.  More space on the left and the top would give it some space to fly into.', '2005-06-29 11:18:11.000000', NULL, 0),
(1490981, 191582, 22734, '<td valign="top">I can see this hanging as a billboard on some architectural convention. The lines are strong and the colors seductive. Congratulations on your top 10 finish.</td>', 'I can see this hanging as a billboard on some architectural convention. The lines are strong and the colors seductive. Congratulations on your top 10 finish.', '2005-06-29 11:19:26.000000', NULL, 0),
